import 'package:flutter_agent_harness/src/cli/subagent_board.dart';
import 'package:flutter_agent_harness/src/cli/tui_text_width.dart';

void main() {
  final t0 = DateTime(2026, 1, 1, 12, 0, 0);
  // Age label cell widths across the hour boundary.
  for (final s in [30, 59, 60, 720, 5400, 3600, 86_400 * 5]) {
    final label = subagentAgeLabel(t0, t0.add(Duration(seconds: s)));
    // ignore: avoid_print
    print('age ${s}s -> "$label" cells=${tuiTextWidth(label)}');
  }
  // Cost label cell widths across bands.
  for (final t in [999, 1000, 4100, 9999, 12345, 41000, 99999, 123456, 123456789]) {
    final label = subagentCompactTokens(t);
    // ignore: avoid_print
    print('cost $t -> "$label" cells=${tuiTextWidth(label)}');
  }
  // Full row at width 100 with a 1h-old agent and a non-round 12.3k cost.
  final rec = SubagentStatusRecord(
    id: 'w',
    name: 'watcher',
    state: SubagentDisplayState.running,
    spawnedAt: t0,
    tokens: 12345,
    preview: 'x' * 80,
  );
  final line = subagentStatusLine(
    rec,
    now: t0.add(const Duration(hours: 1, minutes: 30)),
    width: 100,
  );
  // ignore: avoid_print
  print('row cells=${tuiTextWidth(line)} (budget 100): $line');
}

